import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { supabase } from "../supabase";

const Checkout = ({ cartItems }) => {
  const navigate = useNavigate();

  const [checkingAuth, setCheckingAuth] = useState(true);
  const [placingOrder, setPlacingOrder] = useState(false);

  const [form, setForm] = useState({
    fullName: "",
    phone: "",
    address: "",
    city: "",
    pincode: "",
  });

  useEffect(() => {
    async function checkAuth() {
      const {
        data: { session },
      } = await supabase.auth.getSession();

      if (!session) {
        navigate("/auth");
        return;
      }

      setCheckingAuth(false);
    }

    checkAuth();
  }, [navigate]);

  const subtotal = cartItems.reduce(
    (sum, item) => sum + item.price * item.qty,
    0
  );
  const shipping = subtotal > 999 ? 0 : 99;
  const total = subtotal + shipping;

  const handleChange = (e) => {
    setForm((prev) => ({
      ...prev,
      [e.target.name]: e.target.value,
    }));
  };

  const handlePlaceOrder = async () => {
    if (!cartItems.length) return;

    if (
      !form.fullName ||
      !form.phone ||
      !form.address ||
      !form.city ||
      !form.pincode
    ) {
      alert("Please fill all checkout fields.");
      return;
    }

    setPlacingOrder(true);

    setTimeout(() => {
      alert("Order placed successfully!");
      setPlacingOrder(false);
      navigate("/");
    }, 1000);
  };

  if (checkingAuth) {
    return <div style={{ padding: "2rem" }}>Checking account...</div>;
  }

  return (
    <div style={{ padding: "2rem", maxWidth: "1100px", margin: "0 auto" }}>
      <h1 style={{ marginBottom: "1.5rem" }}>Checkout</h1>

      {cartItems.length === 0 ? (
        <p>Your cart is empty.</p>
      ) : (
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "1.2fr 0.8fr",
            gap: "2rem",
          }}
        >
          <div>
            <h2>Shipping Details</h2>

            <div style={{ display: "grid", gap: "12px", marginTop: "1rem" }}>
              <input
                name="fullName"
                placeholder="Full Name"
                value={form.fullName}
                onChange={handleChange}
                style={inputStyle}
              />
              <input
                name="phone"
                placeholder="Phone Number"
                value={form.phone}
                onChange={handleChange}
                style={inputStyle}
              />
              <textarea
                name="address"
                placeholder="Full Address"
                value={form.address}
                onChange={handleChange}
                style={{ ...inputStyle, minHeight: "100px", resize: "vertical" }}
              />
              <input
                name="city"
                placeholder="City"
                value={form.city}
                onChange={handleChange}
                style={inputStyle}
              />
              <input
                name="pincode"
                placeholder="Pincode"
                value={form.pincode}
                onChange={handleChange}
                style={inputStyle}
              />
            </div>
          </div>

          <div>
            <h2>Order Summary</h2>

            <div style={{ marginTop: "1rem", border: "1px solid #e5e5e5", borderRadius: "12px", padding: "16px" }}>
              {cartItems.map((item) => (
                <div
                  key={item.id}
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    gap: "12px",
                    padding: "12px 0",
                    borderBottom: "1px solid #eee",
                  }}
                >
                  <div>
                    <div style={{ fontWeight: 600 }}>{item.name}</div>
                    <div style={{ color: "#666", fontSize: "14px" }}>
                      Qty: {item.qty}
                    </div>
                  </div>
                  <div>₹{(item.price * item.qty).toLocaleString()}</div>
                </div>
              ))}

              <div style={{ paddingTop: "16px" }}>
                <p>Subtotal: ₹{subtotal.toLocaleString()}</p>
                <p>Shipping: {shipping === 0 ? "FREE" : `₹${shipping}`}</p>
                <h2>Total: ₹{total.toLocaleString()}</h2>

                <button
                  onClick={handlePlaceOrder}
                  disabled={placingOrder}
                  style={{
                    marginTop: "1rem",
                    width: "100%",
                    padding: "14px 18px",
                    border: "none",
                    borderRadius: "10px",
                    background: "#111",
                    color: "#fff",
                    cursor: "pointer",
                    fontWeight: 600,
                  }}
                >
                  {placingOrder ? "Placing Order..." : "Place Order"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const inputStyle = {
  padding: "12px 14px",
  borderRadius: "10px",
  border: "1px solid #ccc",
  width: "100%",
};

export default Checkout;
